module.exports = async (args) => {
  const log=(m)=>args.jobLog(`[Original Language] ${m}\n`);
  const g=args.userVariables?.global||{}; args.variables.user=args.variables.user||{};
  const base=String(args.inputFileObj?._id||'').split('/').pop().replace(/\.[^.]+$/,'');
  const a2={en:'eng',fr:'fre',de:'ger',es:'spa',it:'ita',ja:'jpn',ko:'kor',zh:'chi',pt:'por',ru:'rus',nl:'dut',sv:'swe',no:'nor',da:'dan',fi:'fin',pl:'pol',cs:'cze',tr:'tur',ar:'ara',he:'heb',hi:'hin',th:'tha',vi:'vie',id:'ind',ms:'may',uk:'ukr',ro:'rum',hu:'hun',el:'gre',bg:'bul'};
  const names={english:'eng',french:'fre',german:'ger',spanish:'spa',italian:'ita',japanese:'jpn',korean:'kor',chinese:'chi',portuguese:'por',russian:'rus',dutch:'dut',swedish:'swe',norwegian:'nor',danish:'dan',finnish:'fin',polish:'pol',czech:'cze',turkish:'tur',arabic:'ara',hebrew:'heb',hindi:'hin',thai:'tha',vietnamese:'vie',indonesian:'ind',malay:'may',ukrainian:'ukr',romanian:'rum',hungarian:'hun',greek:'gre',bulgarian:'bul'};
  const url=(u)=>{u=String(u||'').trim();if(!u)return'';if(!/^https?:\/\//i.test(u))u=`http://${u}`;return u.replace(/\/+$/,'')};
  const hdr=(k)=>({'X-Api-Key':String(k||''),Accept:'application/json'}); let original='';
  try { const u=url(g.radarr_url),k=String(g.radarr_api_key||''); if(u&&k){const r=await args.deps.axios({method:'get',url:`${u}/api/v3/parse?title=${encodeURIComponent(base)}`,headers:hdr(k)});const name=String(r?.data?.movie?.originalLanguage?.name||'').toLowerCase();original=names[name]||'';if(original)log(`Radarr: ${name} -> ${original}`)}} catch(err){log(`Radarr lookup skipped/failed: ${err.message||err}`)}
  try { if(!original){const u=url(g.sonarr_url),k=String(g.sonarr_api_key||''),tmdb=String(g.tmdb_api_key||'');if(u&&k){const s=await args.deps.axios({method:'get',url:`${u}/api/v3/parse?title=${encodeURIComponent(base)}`,headers:hdr(k)});const imdb=String(s?.data?.series?.imdbId||'');if(imdb&&tmdb){const t=await args.deps.axios({method:'get',url:`https://api.themoviedb.org/3/find/${encodeURIComponent(imdb)}`,params:{api_key:tmdb,language:'en-US',external_source:'imdb_id'}});const item=(t?.data?.tv_results||[])[0]||(t?.data?.movie_results||[])[0];const code=String(item?.original_language||'').toLowerCase();original=a2[code]||'';if(original)log(`Sonarr/TMDB: ${code} -> ${original}`)}}}} catch(err){log(`Sonarr/TMDB lookup skipped/failed: ${err.message||err}`)}
  args.variables.user.originalLanguage=original||'unknown'; if(!original)log('Unknown original language: audio cleanup will preserve all audio.');
  return {outputFileObj:args.inputFileObj,outputNumber:1,variables:args.variables};
};

module.exports = async (args) => {
  const log=(m)=>args.jobLog(`[Audio Cleanup] ${m}\n`); const ff=args.variables?.ffmpegCommand;
  if(!ff||!Array.isArray(ff.streams))throw new Error('FFmpeg command is not initialized');
  const original=String(args.variables?.user?.originalLanguage||'unknown').toLowerCase();
  const a2={en:'eng',fr:'fre',de:'ger',es:'spa',it:'ita',ja:'jpn',ko:'kor',zh:'chi',pt:'por',ru:'rus',nl:'dut'};
  const lang=(v)=>{const s=String(v||'und').toLowerCase().replace('_','-');if(s==='en'||s.startsWith('en-'))return'eng';return a2[s]||s.slice(0,3)};
  const comm=(s)=>/commentary|audio description|descriptive/i.test(String(s?.tags?.title||''));
  const rank=(s)=>{const c=String(s.codec_name||'').toLowerCase(),p=String(s.profile||'').toLowerCase();let x=comm(s)?0:20000;if(c==='truehd')x+=10000;else if(c==='flac')x+=9500;else if(c==='dts'&&/ma|master/i.test(p))x+=9000;else if(c==='dts')x+=8000;else if(c==='eac3')x+=7000;else if(c==='ac3')x+=6000;else if(c==='opus')x+=5500;else if(c==='aac')x+=5000;x+=Number(s.channels||0)*100;x+=Math.min(Number(s.bit_rate||0)/100000,500);return x};
  const audio=ff.streams.filter(s=>s.codec_type==='audio'&&!s.removed); if(!audio.length)return {outputFileObj:args.inputFileObj,outputNumber:1,variables:args.variables};
  if(!original||original==='unknown'){log('Original language unknown: preserving ALL audio.');return {outputFileObj:args.inputFileObj,outputNumber:1,variables:args.variables}}
  const keep=new Set(); for(const wanted of [...new Set([original,'eng'])]){let c=audio.filter(s=>lang(s?.tags?.language)===wanted);if(!c.length&&wanted===original)c=audio.filter(s=>lang(s?.tags?.language)==='und');c.sort((a,b)=>rank(b)-rank(a));if(c[0])keep.add(c[0])}
  if(!keep.size)keep.add([...audio].sort((a,b)=>rank(b)-rank(a))[0]); let removed=0; for(const s of audio){if(!keep.has(s)){s.removed=true;removed++}}
  if(removed)ff.shouldProcess=true; log(`Kept ${keep.size} best original/English audio track(s); removed ${removed}. Audio remains stream-copy.`);
  return {outputFileObj:args.inputFileObj,outputNumber:1,variables:args.variables};
};

module.exports = async (args) => {
  const log=(m)=>args.jobLog(`[Subtitle Cleanup] ${m}\n`);const ff=args.variables?.ffmpegCommand;if(!ff||!Array.isArray(ff.streams))throw new Error('FFmpeg command is not initialized');
  const lang=(v)=>{const s=String(v||'und').toLowerCase().replace('_','-');return(s==='en'||s.startsWith('en-'))?'eng':s.slice(0,3)};let kept=0,removed=0;
  for(const s of ff.streams.filter(s=>s.codec_type==='subtitle'&&!s.removed)){const title=String(s?.tags?.title||'');const forced=s?.disposition?.forced===1||s?.disposition?.forced===true||/\bforced\b/i.test(title);if(lang(s?.tags?.language)==='eng'||forced)kept++;else{s.removed=true;removed++}}
  if(removed)ff.shouldProcess=true;log(`Kept ${kept} English/forced subtitle(s); removed ${removed}.`);
  return {outputFileObj:args.inputFileObj,outputNumber:1,variables:args.variables};
};

module.exports = async (args) => {
  const ff=args.variables?.ffmpegCommand;
  if(!ff||!Array.isArray(ff.streams))throw new Error('FFmpeg command is not initialized');
  for(const s of ff.streams){
    if(s.codec_type==='video'&&!s.removed){
      // Tdarr's generic 10-bit plugin currently emits AV1 profile "main10" for QSV,
      // which ffmpeg av1_qsv rejects. AV1 10-bit is Main profile + P010 surfaces.
      s.outputArgs.push('-profile:v:{outputTypeIndex}','main');
      s.outputArgs.push('-vf','scale_qsv=format=p010le');
    }
  }
  args.jobLog('[10-bit QSV] Using AV1 Main profile with scale_qsv=format=p010le.\n');
  return {outputFileObj:args.inputFileObj,outputNumber:1,variables:args.variables};
};
